function SmoothAccordionFaq() {
  const theme = {
    surface: "bg-white dark:bg-zinc-950",
    border: "border-zinc-200 dark:border-zinc-800",
    text: "text-zinc-900 dark:text-zinc-50",
    muted: "text-zinc-500 dark:text-zinc-400",
    accent: "text-violet-600 dark:text-violet-400",
    iconBg: "bg-zinc-100 dark:bg-zinc-900",
  };

  const faqs = [
    { id: "1", q: "What is included in the trial?", a: "Full access to core features for 14 days. No card required to start." },
    { id: "2", q: "Can I change plans later?", a: "Yes. Upgrade or downgrade anytime; changes apply on your next billing cycle." },
    { id: "3", q: "How do I cancel?", a: "Cancel from billing settings. You keep access until the end of the paid period." },
    { id: "4", q: "Do you offer refunds?", a: "We offer refunds within 14 days of first payment if the product is not a fit." },
  ];

  const [openId, setOpenId] = useState<string | null>(faqs[0]?.id ?? null);

  return (
    <section className={cn("w-full max-w-3xl mx-auto px-4 py-16", theme.surface)}>
      <h2 className={cn("text-3xl font-semibold tracking-tight mb-2", theme.text)}>FREQUENTLY ASKED QUESTIONS</h2>
      <p className={cn("mb-10 text-base", theme.muted)}>Quick answers about getting started and billing.</p>
      <div className={cn("rounded-2xl border overflow-hidden", theme.border)}>
        {faqs.map((item, index) => {
          const isOpen = openId === item.id;
          return (
            <div key={item.id} className={cn(index !== 0 && "border-t", theme.border)}>
              <button
                type="button"
                onClick={() => setOpenId(isOpen ? null : item.id)}
                className={cn("flex w-full items-center justify-between gap-4 px-5 py-4 text-left transition-colors hover:bg-zinc-50/80 dark:hover:bg-zinc-900/50", theme.text)}
                aria-expanded={isOpen}
              >
                <span className="font-medium pr-2">{item.q}</span>
                <span className={cn("flex h-9 w-9 shrink-0 items-center justify-center rounded-full transition-transform duration-300", theme.iconBg, isOpen && "rotate-180")}>
                  {isOpen ? <Minus className="h-4 w-4" /> : <Plus className="h-4 w-4" />}
                </span>
              </button>
              <AnimatePresence initial={false}>
                {isOpen && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: "auto", opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.28, ease: [0.4, 0, 0.2, 1] }}
                    className="overflow-hidden"
                  >
                    <div className={cn("px-5 pb-5 pt-0 text-sm leading-relaxed border-t border-transparent", theme.muted)}>
                      {item.a}{" "}
                      <a href="#" data-vibey-link className={cn("font-medium underline-offset-2 hover:underline", theme.accent)}>
                        Learn more
                      </a>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          );
        })}
      </div>
    </section>
  );
}


