function TwoColumnSplitFaq() {
  const theme = {
    surface: "bg-zinc-50 dark:bg-black",
    card: "bg-white dark:bg-zinc-950",
    border: "border-zinc-200 dark:border-zinc-800",
    text: "text-zinc-900 dark:text-zinc-50",
    muted: "text-zinc-500 dark:text-zinc-400",
    active: "bg-violet-600 text-white dark:bg-violet-500",
    inactive: "hover:bg-zinc-100 dark:hover:bg-zinc-900",
    panel: "border-violet-200/60 dark:border-violet-900/40",
  };

  const faqs = [
    { id: "a", q: "Is there a free tier?", a: "Yes. The free tier includes core workflows and limited automation runs per month." },
    { id: "b", q: "What integrations are supported?", a: "Slack, email, webhooks, and major CRMs. Enterprise adds custom connectors." },
    { id: "c", q: "Where is data hosted?", a: "Regions include US and EU. You can pick at workspace creation; migration is available on Enterprise." },
    { id: "d", q: "Who can I contact for security review?", a: "Email security@example.com for our SOC2 pack, DPA, and subprocessors list." },
  ];

  const [selectedId, setSelectedId] = useState(faqs[0]?.id ?? "");

  const selected = faqs.find((f) => f.id === selectedId) ?? faqs[0];

  return (
    <section className={cn("w-full max-w-6xl mx-auto px-4 py-16", theme.surface)}>
      <h2 className={cn("text-3xl font-semibold tracking-tight mb-2", theme.text)}>FREQUENTLY ASKED QUESTIONS</h2>
      <p className={cn("mb-10 max-w-2xl", theme.muted)}>Pick a question to read the full answer.</p>

      <div className="hidden lg:flex flex-row gap-10">
        <div className={cn("flex-1 rounded-2xl border p-2 space-y-1", theme.card, theme.border)}>
          {faqs.map((item) => {
            const on = selectedId === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => setSelectedId(item.id)}
                className={cn(
                  "w-full rounded-xl px-4 py-3 text-left text-sm font-medium transition-colors",
                  on ? theme.active : cn(theme.text, theme.inactive),
                )}
              >
                {item.q}
              </button>
            );
          })}
        </div>

        <div className={cn("flex-1 min-h-[220px] rounded-2xl border p-8 shadow-sm", theme.card, theme.border, theme.panel)}>
          <AnimatePresence mode="wait">
            <motion.div
              key={selected?.id}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -6 }}
              transition={{ duration: 0.22 }}
            >
              <p className={cn("text-xs font-semibold uppercase tracking-wider mb-3", theme.muted)}>Answer</p>
              <h3 className={cn("text-lg font-semibold mb-3", theme.text)}>{selected?.q}</h3>
              <p className={cn("text-base leading-relaxed", theme.muted)}>{selected?.a}</p>
              <a href="#" data-vibey-link className={cn("inline-flex mt-6 text-sm font-medium text-violet-600 dark:text-violet-400 underline-offset-2 hover:underline")}>
                Related docs
              </a>
            </motion.div>
          </AnimatePresence>
        </div>
      </div>

      <div className="lg:hidden space-y-2">
        {faqs.map((item) => (
          <details key={item.id} className={cn("rounded-xl border px-4 py-3", theme.card, theme.border)}>
            <summary className={cn("cursor-pointer font-medium", theme.text)}>{item.q}</summary>
            <p className={cn("mt-2 text-sm", theme.muted)}>{item.a}</p>
          </details>
        ))}
