const DraggableTestimonials = () => {
  const testimonials = [
    { id: 1, quote: 'This completely transformed how we approach our business. The results speak for themselves.', author: 'Sarah Chen, CEO' },
    { id: 2, quote: 'The team went above and beyond. We saw a 3x improvement in our first quarter.', author: 'Marcus Rivera, COO' },
    { id: 3, quote: 'Best investment we made this year. The ROI was immediate and measurable.', author: 'Amara Okafor, VP Growth' },
  ];

  const [order, setOrder] = useState(testimonials.map((_, i) => i));
  const dragRef = useRef(0);

  const shuffle = () => setOrder(prev => { const n = [...prev]; n.push(n.shift()); return n; });

  const positions = ['front', 'middle', 'back'];

  return (
    <section className="py-24 md:py-32" style={{ background: theme.bg }}>
      <div className="max-w-7xl mx-auto px-6">
        <div className="text-center mb-16">
          <h2 className="text-3xl md:text-4xl font-bold" style={{ color: theme.text }}>What people are saying</h2>
          <p className="mt-3 text-sm" style={{ color: theme.textMuted }}>Drag to see more</p>
        </div>

        <div className="relative h-[480px] w-[350px] mx-auto">
          {order.map((idx, posIndex) => {
            const t = testimonials[idx];
            const pos = positions[posIndex];
            const isFront = pos === 'front';

            return (
              <motion.div
                key={t.id}
                style={{ zIndex: pos === 'front' ? 3 : pos === 'middle' ? 2 : 1 }}
                animate={{
                  rotate: pos === 'front' ? '-6deg' : pos === 'middle' ? '0deg' : '6deg',
                  x: pos === 'front' ? '0%' : pos === 'middle' ? '33%' : '66%',
                }}
                drag={isFront}
                dragElastic={0.35}
                dragConstraints={{ top: 0, left: 0, right: 0, bottom: 0 }}
                onDragStart={(e) => { dragRef.current = e.clientX; }}
                onDragEnd={(e) => { if (dragRef.current - e.clientX > 150) shuffle(); dragRef.current = 0; }}
